/** One actorless typed upgrade, compatible neighbor merge, then actual abrupt partial-save recovery. */
@net.neoforged.fml.common.EventBusSubscriber(modid="vandorlabs")
public final class NativeLegacyMigrationChecks {
 private static ServerLevel world;private static net.neoforged.neoforge.common.util.FakePlayer actor;private static int ticks,stage,checks,pause;private static boolean running,halting;
 private static NativeCellTransactions.Operation<?> operation;private static CompoundTag original;private static UUID identity;
 private static String phase(){return System.getProperty("vandorlabs.legacyMigrationPhase","");}
 private static BlockPos source(){return new BlockPos(phase().equals("write")?15:47,112,8);}
 private static BlockPos destination(){return source().east();}
 private static void need(boolean value,String why){checks++;if(!value)throw new AssertionError("Legacy migration stage="+stage+" tick="+ticks+": "+why);}
 private static NativeLegacyLandingEntity old(BlockPos pos){return NativeLegacyLandingBlock.owner(world,pos);}
 private static NativeGearEntity gear(BlockPos pos){var member=NativeGearFormation.at(world,pos);return member==null?null:member.controllerEntity();}
 @net.neoforged.bus.api.SubscribeEvent public static void start(net.neoforged.neoforge.event.server.ServerStartedEvent event){if(phase().isEmpty())return;world=event.getServer().overworld();actor=net.neoforged.neoforge.common.util.FakePlayerFactory.getMinecraft(world);actor.setGameMode(GameType.SURVIVAL);for(int x=13;x<=51;x++){world.setChunkForced(x>>4,0,true);world.getChunkAt(new BlockPos(x,112,8));}running=true;}
 @net.neoforged.bus.api.SubscribeEvent public static void tick(net.neoforged.neoforge.event.tick.ServerTickEvent.Post event){if(!running)return;try{need(++ticks<500,"bounded asynchronous migration status="+(operation==null?"none":operation.status()+" "+operation.error()));if(ticks<15)return;if(halting)return;
 if(stage==0){if(phase().equals("recover")){original=NbtIo.readCompressed(file(),NbtAccounter.create(2*1024*1024));var root=old(source());need(root!=null&&!root.inert()&&same(original,root.saveWithFullMetadata(world.registryAccess())),"cold ARMED recovery restores complete original owner fields");need(gear(destination())==null&&world.getEntitiesOfClass(ItemEntity.class,new AABB(source()).inflate(8)).isEmpty(),"cold rollback has no modular or loose duplicate owner");identity=root.identity();need(root.pristine(),"cold vanilla false storage metadata remains eligible for exact typed migration");for(int variant=0;variant<3;variant++){var raw=root.saveWithFullMetadata(world.registryAccess());if(variant==0)raw.putBoolean("keepPacked",true);else if(variant==1)raw.putInt("keepPacked",0);else{var caps=new CompoundTag();caps.putString("opaque:fixture","retain exactly");raw.put("ForgeCaps",caps);}var staged=new NativeLegacyLandingEntity(root.getBlockPos(),root.getBlockState());staged.setLevel(world);staged.loadWithComponents(raw,world.registryAccess());need(!staged.pristine(),"true/wrong-type storage hints and opaque capabilities are never discarded by migration");}stage=1;return;}if(phase().equals("crash")){var previous=gear(new BlockPos(16,112,8));need(previous!=null&&previous.columns().size()==2&&previous.progress()==0&&!previous.target()&&previous.settings().legacyAnyChannels()&&previous.getPersistentData().getString("LegacyNeighbor").equals("retained"),"successful merged native group persists across real restart");}place(source());var root=old(source());identity=root.identity();original=root.saveWithFullMetadata(world.registryAccess());NbtIo.writeCompressed(original,file());world.getServer().saveEverything(true,true,true);stage=1;return;}
 if(stage==1){operation=NativeLegacyMigration.request(old(source()));if(operation==null)return;need(operation.status()==NativeCellTransactions.Status.PENDING&&old(source())!=null,"real pending disk preparation leaves legacy owner usable");if(phase().equals("write"))world.noSave=true;if(phase().equals("crash"))NativeLegacyMigration.fault=(header,cell)->{if(cell.pos.equals(source())&&cell.state.isAir()){need(operation.mutationArmed()&&old(source())==null&&gear(destination())==null,"actual durable ARMED source retirement precedes new root publication");need((source().getX()>>4)!=(destination().getX()>>4),"genuine cross-chunk ownership boundary");world.noSave=true;halting=true;var at=new net.minecraft.world.level.ChunkPos(source());var chunk=world.getChunkSource().getChunkNow(at.x,at.z);world.getChunkSource().chunkMap.write(at,net.minecraft.world.level.chunk.storage.ChunkSerializer.write(world,chunk)).thenCompose(unused->((com.vandorlabs.neoforge.mixin.NativeRampChunkStorageAccess)(Object)world.getChunkSource().chunkMap).vandorlabs$rampWorker().synchronize(true)).whenComplete((unused,failure)->{if(failure!=null){failure.printStackTrace();System.out.flush();Runtime.getRuntime().halt(2);}System.out.println("[vandorlabs][legacy-migration] crash PASS checks="+checks+" maintenanceARMED/sourceOnlyCrossChunkSave/noNativeRoot/abruptHalt");System.out.flush();Runtime.getRuntime().halt(0);});throw new IllegalStateException("Deliberate source-only partial-save checkpoint");}};stage=2;return;}
 if(operation.status()==NativeCellTransactions.Status.FAILED)throw new AssertionError(operation.error());
 if(stage==2){if(world.noSave){if(!operation.protects(source()))return;need(!operation.mutationArmed()&&old(source())!=null,"disabled saving pauses actual prepared maintenance before removal");if(++pause<3)return;world.noSave=false;}if(operation.status()!=NativeCellTransactions.Status.DONE)return;need(operation.error().isEmpty(),"successful maintenance has no hidden rollback "+operation.error());var root=gear(destination());need(root!=null&&root.identity().equals(identity)&&root.definition()==NativeGearDefinition.LARGE_EXTENDER&&root.assembly().columnHeight()==2&&root.assembly().feet().size()==4&&root.progress()==0&&!root.target()&&root.settings().trigger()==0&&root.settings().legacyAnyChannels(),"one fully formed Large native group retains input and stowed endpoint");need(world.getBlockState(source()).isAir()&&world.getEntitiesOfClass(ItemEntity.class,new AABB(source()).inflate(8)).isEmpty(),"legacy owner retired without a loose duplicate");need(!NativeTransferHolds.active(world),"reservation retires after durable native publication");need(root.command(true),"converted ordinary mechanism deploys");stage=3;return;}
 if(stage==3){var root=gear(destination());if(root.progress()!=1){need(!root.blocked(),"converted deploy blocked: "+root.error());return;}need(root.command(false),"converted mechanism reverses");stage=4;return;}
 if(stage==4){var root=gear(destination());if(root.progress()!=0){need(!root.blocked(),"converted reversal blocked: "+root.error());return;}if(phase().equals("recover")){done();return;}need(root.command(true),"return deployed for compatible merge");stage=5;return;}
 if(stage==5){var root=gear(destination());if(root.progress()!=1)return;root.getPersistentData().putString("LegacyNeighbor","retained");root.setChanged();var next=source().east(2);place(next);need(old(next).target(actor,true),"neighbor legacy deployment");stage=6;return;}
 if(stage==6){var next=source().east(2);if(old(next).progress()!=2)return;operation=NativeLegacyMigration.request(old(next));if(operation==null)return;stage=7;return;}
 if(stage==7){if(operation.status()!=NativeCellTransactions.Status.DONE)return;need(operation.error().isEmpty(),"compatible native neighbor merge completed "+operation.error());var root=gear(destination());need(root!=null&&root.columns().size()==2&&root.assembly().feet().size()==8&&gear(destination().east(2))==root,"complete group merges into exactly one native controller");need(root.getPersistentData().getString("LegacyNeighbor").equals("retained"),"native neighbor opaque envelope retained exactly");need(root.command(false),"joined migrated group reverses");stage=8;return;}
 if(stage==8){var root=gear(destination());if(root.progress()!=0){need(!root.blocked(),"joined migrated reversal blocked: "+root.error());return;}done();}
 }catch(Throwable failure){fail(failure);}}
 private static void place(BlockPos pos){world.setBlock(pos.above(),Blocks.STONE.defaultBlockState(),3);world.setBlock(pos.east().above(),Blocks.STONE.defaultBlockState(),3);actor.setPos(pos.getX()+.5,pos.getY()-1,pos.getZ()-3);actor.setYRot(Direction.WEST.toYRot());actor.setShiftKeyDown(false);var stack=new ItemStack(NativeLegacyLandingBindings.ITEMS.get(NativeLegacyLandingKind.WHEEL));actor.setItemInHand(InteractionHand.MAIN_HAND,stack);var result=actor.gameMode.useItemOn(actor,world,stack,InteractionHand.MAIN_HAND,new BlockHitResult(Vec3.atCenterOf(pos.above()).add(0,-.5,0),Direction.DOWN,pos.above(),false));need(result.consumesAction()&&stack.isEmpty()&&old(pos)!=null,"one actual Survival legacy placement");need(old(pos).getBlockState().getValue(NativeLegacyLandingBlock.FACING)==Direction.EAST,"Source Large East root-shift case");need(old(pos).configure(actor,new NativeLegacyLandingData.Configuration(0,ChannelList.EMPTY,32,4)),"configured Large source with two-block travel");}
 private static Path file(){return world.getServer().getWorldPath(net.minecraft.world.level.storage.LevelResource.ROOT).resolve("legacy-migration-original.nbt");}
 private static boolean same(CompoundTag expected,CompoundTag actual){var a=expected.copy();var b=actual.copy();for(var tag:List.of(a,b)){if(tag.contains("keepPacked",Tag.TAG_BYTE)&&tag.getByte("keepPacked")==0)tag.remove("keepPacked");if(tag.contains("NeoForgeData",Tag.TAG_COMPOUND)&&tag.getCompound("NeoForgeData").isEmpty())tag.remove("NeoForgeData");}return a.equals(b);}
 private static void done(){running=false;NativeLegacyMigration.fault=null;world.getServer().saveEverything(true,true,true);System.out.println("[vandorlabs][legacy-migration] "+phase()+" PASS checks="+checks+" realAsyncMaintenance/NoSave/fullGroup/opaqueNeighbor/reversal/oneOwner");world.getServer().halt(false);}
 private static void fail(Throwable failure){running=false;failure.printStackTrace();System.out.println("[vandorlabs][legacy-migration] "+phase()+" FAIL "+failure);if(world!=null){world.noSave=false;world.getServer().halt(false);}}
 private NativeLegacyMigrationChecks(){}
}
